import assert from 'node:assert/strict';
import test from 'node:test';
import { seal, unseal } from '../services/browser-login/credential-envelope.mjs';

const key = Buffer.alloc(32, 7);
const payload = { password: 'synthetic legacy password', username: 'synthetic-account' };
// Generated by the original v1 implementation using synthetic values only.
const legacy = '{"v":1,"nonce":"6wZHbIUV7C4axIb3","data":"5JsA48CZtj5hSXrUoFangWkR/ixuBJ+/z9bG3eUsLh82rg+A4CrXqhboHnqD382p02NCwRr38coKmMjR/dqvZ95qiIhwIGU=","tag":"OOJoli7YRFbEL+wjTK2ILQ=="}';

test('saved v1 login envelopes remain readable after separating shared crypto', () => {
  assert.deepEqual(unseal(key, 'owner-a', 'credential-a', legacy), payload);
});

test('envelopes bind ciphertext to its owner and credential identity', () => {
  const encoded = seal(key, 'owner-a', 'credential-a', payload);
  assert.deepEqual(unseal(key, 'owner-a', 'credential-a', encoded), payload);
  assert.throws(() => unseal(key, 'owner-b', 'credential-a', encoded));
  assert.throws(() => unseal(key, 'owner-a', 'credential-b', encoded));
  assert.throws(() => unseal(Buffer.alloc(32, 8), 'owner-a', 'credential-a', encoded));
});

test('saved envelopes use independent nonces and reject modified ciphertext', () => {
  const first = seal(key, 'owner-a', 'credential-a', payload);
  const second = seal(key, 'owner-a', 'credential-a', payload);
  assert.notEqual(JSON.parse(first).nonce, JSON.parse(second).nonce);
  const modified = JSON.parse(first);
  const bytes = Buffer.from(modified.data, 'base64');
  bytes[0] ^= 1;
  modified.data = bytes.toString('base64');
  assert.throws(() => unseal(key, 'owner-a', 'credential-a', JSON.stringify(modified)));
  assert.throws(() => unseal(key, 'owner-a', 'credential-a', JSON.stringify({ ...modified, v: 2 })));
});
